from typing import List


def difference_calculator(n: int, arr: List[int]) -> int:
    ind1 = 0
    i = 0
    while i < n:
        j = i
        while j < n and arr[j] == arr[i]:
            j += 1
        if j - i == arr[i]:
            ind1 += 1
        i = j

    ind2 = 0
    for k in range(1, n + 1):  # 1-based index
        if arr[k - 1] != k:
            continue
        j = k - 1
        while j < n and arr[j] == k:
            j += 1
        if j - (k - 1) == k:  # exactly k copies of k from index k on
            ind2 += 1
    return abs(ind1 - ind2)
